function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

function escInt(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  const n = parseInt(String(v).trim(), 10);
  return Number.isFinite(n) ? String(n) : 'NULL';
}

function escInterval(v) {
  if (!v) return 'NULL';
  const s = /^\d{1,2}:\d{2}$/.test(v) ? '00:' + v : v;
  return `INTERVAL ${esc(s)}`;
}

function escTime(v) {
  if (!v) return 'NULL';
  return `TIME ${esc(v)}`;
}

function parseMember(s) {
  const m = String(s).match(/^(.*?)\s*\(([A-Z]{2,3})\)\s*$/);
  if (m) return { name: m[1].trim(), country: m[2] };
  return { name: String(s).trim(), country: null };
}

function countryEq(c) {
  return c ? `= ${esc(c)}` : `IS NULL`;
}

const item = $input.item.json;

const event_id = item.event_id || $('Edit Fields').first().json.event_id;
const idp = item.idp || (item.detail_url ? item.detail_url.match(/[?&]idp=([^&#]*)/)?.[1] : null);

if (!event_id || !idp) {
  throw new Error(`Missing event_id or idp. event_id=${event_id}, idp=${idp}`);
}

const season = item.season || 'season-8';
const detail_url = item.detail_url || null;

const details = Array.isArray(item.individual_details) ? item.individual_details : [];
const workout = Array.isArray(item.workout_summary) ? item.workout_summary : [];
const replay = Array.isArray(item.race_replay) ? item.race_replay : [];

const sectionItems = (title) => {
  const s = details.find((d) => d.title === title);
  return s && s.items ? s.items : {};
};

const raceDetails = sectionItems('Race Details');
const team = {
  ...sectionItems('Doubles Team'),
  ...sectionItems('Individual'),
};

let membersRaw = sectionItems('Members');

if (!membersRaw || Object.keys(membersRaw).length === 0) {
  const name =
    item.member ||
    team['Name'] ||
    (team['Firstname'] || team['Lastname']
      ? `${team['Lastname'] || ''}, ${team['Firstname'] || ''}`.trim()
      : null);

  membersRaw = name
    ? {
        'Member 1': item.country ? `${name} (${item.country})` : name,
      }
    : {};
}

const judging = sectionItems('Judging Decision');
const overall = sectionItems('Overall Time');

const members = [];
const seen = new Set();

for (const raw of Object.values(membersRaw || {})) {
  if (!raw) continue;
  const parsed = parseMember(raw);
  const key = `${parsed.name}|${parsed.country || ''}`;
  if (seen.has(key)) continue;
  seen.add(key);
  members.push(parsed);
}

const stmts = [];
const RES_ID_SUBQ = `(SELECT result_id FROM results WHERE event_id = ${esc(event_id)} AND idp = ${esc(idp)})`;

stmts.push(`
INSERT INTO events (event_id, season, race_name, division)
VALUES (${esc(event_id)}, ${esc(season)}, ${esc(raceDetails['Race'])}, ${esc(raceDetails['Division'])})
ON CONFLICT (event_id) DO UPDATE
SET season = COALESCE(EXCLUDED.season, events.season),
    race_name = COALESCE(EXCLUDED.race_name, events.race_name),
    division = COALESCE(EXCLUDED.division, events.division);
`.trim());

for (const a of members) {
  if (a.country) {
    stmts.push(`
INSERT INTO athletes (name, country)
VALUES (${esc(a.name)}, ${esc(a.country)})
ON CONFLICT (name, country) DO NOTHING;
`.trim());
  } else {
    stmts.push(`
INSERT INTO athletes (name, country)
SELECT ${esc(a.name)}, NULL
WHERE NOT EXISTS (
  SELECT 1 FROM athletes WHERE name = ${esc(a.name)} AND country IS NULL
);
`.trim());
  }
}

stmts.push(`
INSERT INTO results (
  event_id, idp, bib_number, age_group,
  rank_overall, rank_age_group, overall_time,
  bonus, penalty, disqual_reason, info, detail_url
) VALUES (
  ${esc(event_id)}, ${esc(idp)}, ${esc(team['Bib Number'])}, ${esc(team['Age Group'] || item.age_group)},
  ${escInt(overall['Rank (M/W)'] || item.rank)}, ${escInt(overall['Rank (AG)'] || item.rank_age_group)}, ${escInterval(overall['Overall Time'] || item.total)},
  ${esc(judging['*Bonus'])}, ${esc(judging['*Penalty'])}, ${esc(judging['Disqual Reason'])}, ${esc(judging['Info'])},
  ${esc(detail_url)}
)
ON CONFLICT (event_id, idp) DO UPDATE SET
  bib_number = EXCLUDED.bib_number,
  age_group = EXCLUDED.age_group,
  rank_overall = EXCLUDED.rank_overall,
  rank_age_group = EXCLUDED.rank_age_group,
  overall_time = EXCLUDED.overall_time,
  bonus = EXCLUDED.bonus,
  penalty = EXCLUDED.penalty,
  disqual_reason = EXCLUDED.disqual_reason,
  info = EXCLUDED.info,
  detail_url = EXCLUDED.detail_url;
`.trim());

stmts.push(`DELETE FROM result_members WHERE result_id = ${RES_ID_SUBQ};`);
stmts.push(`DELETE FROM workout_splits WHERE result_id = ${RES_ID_SUBQ};`);
stmts.push(`DELETE FROM race_replay_splits WHERE result_id = ${RES_ID_SUBQ};`);

members.forEach((a, i) => {
  stmts.push(`
INSERT INTO result_members (result_id, member_position, athlete_id)
SELECT r.result_id, ${i + 1}, a.athlete_id
FROM results r, athletes a
WHERE r.event_id = ${esc(event_id)} AND r.idp = ${esc(idp)}
  AND a.name = ${esc(a.name)} AND a.country ${countryEq(a.country)};
`.trim());
});

workout.forEach((s, i) => {
  stmts.push(`
INSERT INTO workout_splits (result_id, position, split_name, split_time, place)
SELECT result_id, ${i + 1}, ${esc(s.Split)}, ${escInterval(s.Time)}, ${escInt(s.Place)}
FROM results WHERE event_id = ${esc(event_id)} AND idp = ${esc(idp)};
`.trim());
});

replay.forEach((s, i) => {
  stmts.push(`
INSERT INTO race_replay_splits (result_id, position, split_name, time_of_day, elapsed_time, diff)
SELECT result_id, ${i + 1}, ${esc(s.Split)}, ${escTime(s['Time Of Day'])}, ${escInterval(s.Time)}, ${escInterval(s.Diff)}
FROM results WHERE event_id = ${esc(event_id)} AND idp = ${esc(idp)};
`.trim());
});

return {
  json: {
    query: ['BEGIN;', ...stmts, 'COMMIT;'].join('\n\n')
  }
};

// n8n Code node — extract HYROX results from HTML in json.data
// Mode: Run Once for All Items

const BASE_URL = 'https://results.hyrox.com/season-8/';

function stripTags(s) {
  return s.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
}

function decodeEntities(s) {
  return s
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ');
}

function dedupeNames(s) {
  const parts = s.split(',').map(p => p.trim()).filter(Boolean);
  const out = [];
  for (const p of parts) if (!out.includes(p)) out.push(p);
  return out.join(', ');
}

function buildDetailUrl(href) {
  if (!href) return null;
  const decoded = decodeEntities(href);
  if (/^https?:\/\//i.test(decoded)) return decoded;
  return BASE_URL.replace(/\/+$/, '/') + decoded.replace(/^\/+/, '');
}

function getQueryParam(url, key) {
  if (!url) return null;

  const decoded = decodeEntities(url);
  const m = decoded.match(new RegExp('[?&]' + key + '=([^&#]*)'));

  return m ? decodeURIComponent(m[1]) : null;
}

function parseHyroxResults(html, itemCountry) {
  const liRegex = /<li class="([^"]*list-group-item[^"]*)"[^>]*>([\s\S]*?)<\/li>/g;
  const labelRegex = /<div class="[^"]*list-label[^"]*"[^>]*>[\s\S]*?<\/div>/;

  const rows = [];
  const seen = new Set();
  let m;

  while ((m = liRegex.exec(html)) !== null) {
    const cls = m[1];
    const content = m[2];

    if (cls.includes('list-group-header')) continue;

    const rankM = content.match(/<div class="[^"]*place-primary[^"]*"[^>]*>([^<]+)<\/div>/);
    const ageRankM = content.match(/<div class="[^"]*place-secondary[^"]*"[^>]*>([^<]+)<\/div>/);
    const linkM = content.match(/<h4[^>]*type-fullname[^>]*>\s*<a[^>]*\shref="([^"]*)"[^>]*>([\s\S]*?)<\/a>/);

    const ageBlockM = content.match(/<div class="[^"]*type-age_class[^"]*"[^>]*>([\s\S]*?)<\/div>\s*<\/div>/);
    const timeBlockM = content.match(/<div class="[^"]*type-time[^"]*"[^>]*>([\s\S]*?)<\/div>\s*<\/div>/);
    const countryM = content.match(/<span class="nation__abbr">([^<]+)<\/span>/);

    if (!rankM || !linkM) continue;

    const country = countryM ? countryM[1].trim() : null;

    const detail_url = buildDetailUrl(linkM[1]);
    const idp = getQueryParam(detail_url, 'idp');

    const dedupKey = idp || linkM[2];
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);

    const ageGroup = ageBlockM
      ? stripTags(ageBlockM[1].replace(labelRegex, ''))
      : null;

    const total = timeBlockM
      ? stripTags(timeBlockM[1].replace(labelRegex, ''))
      : null;

    rows.push({
      rank: parseInt(rankM[1].trim(), 10),
      rank_age_group: ageRankM ? parseInt(ageRankM[1].trim(), 10) : null,
      member: dedupeNames(decodeEntities(stripTags(linkM[2]))),
      country,
      age_group: ageGroup,
      total,
      detail_url,
      idp,
    });
  }

  return rows;
}

const output = [];

for (const item of $input.all()) {
  const html = item.json.data;
  const wantedCountry = item.json.country;

  if (typeof html !== 'string' || !html) continue;

  for (const row of parseHyroxResults(html, wantedCountry)) {
    if (wantedCountry && row.country !== wantedCountry) continue;

    output.push({
      json: {
        ...item.json,
        ...row,
      },
    });
  }
}

return output;

// n8n Code node — extract Individual's Details, Workout Summary,
// and Race Replay from a HYROX detail page. HTML in json.data.
// Mode: Run Once for Each Item

function stripTags(s) {
  return String(s).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
}

function decodeEntities(s) {
  return String(s)
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&ndash;/g, '-')
    .replace(/&mdash;/g, '-');
}

function clean(s) {
  return decodeEntities(stripTags(s));
}

function nullIfBlank(v) {
  if (v === undefined || v === null) return null;
  if (v === '-' || v === '') return null;
  return v;
}

function getQueryParam(url, key) {
  if (!url) return null;
  const decoded = decodeEntities(url);
  const m = decoded.match(new RegExp('[?&]' + key + '=([^&#]*)'));
  return m ? decodeURIComponent(m[1]) : null;
}

function extractById(html, id, span = 30000) {
  const re = new RegExp(`<div[^>]*id="${id}"[^>]*>`);
  const m = re.exec(html);
  return m ? html.slice(m.index, m.index + span) : null;
}

function extractFirstTable(scope) {
  if (!scope) return null;
  const m = scope.match(/<table[^>]*>([\s\S]*?)<\/table>/);
  return m ? m[1] : null;
}

function parseTable(tableHtml) {
  if (!tableHtml) return [];

  const theadM = tableHtml.match(/<thead[^>]*>([\s\S]*?)<\/thead>/);
  const headerScope = theadM ? theadM[1] : tableHtml;
  const headers = [];
  const thRe = /<th[^>]*>([\s\S]*?)<\/th>/g;

  let hm;
  while ((hm = thRe.exec(headerScope)) !== null) {
    headers.push(clean(hm[1]));
  }

  const tbodyM = tableHtml.match(/<tbody[^>]*>([\s\S]*?)<\/tbody>/);
  const bodyScope = tbodyM
    ? tbodyM[1]
    : tableHtml.replace(/<thead[\s\S]*?<\/thead>/, '');

  const rows = [];
  const rowRe = /<tr[^>]*>([\s\S]*?)<\/tr>/g;

  let rm;
  while ((rm = rowRe.exec(bodyScope)) !== null) {
    const cellRe = /<(?:th|td)[^>]*>([\s\S]*?)<\/(?:th|td)>/g;
    const cells = [];

    let cm;
    while ((cm = cellRe.exec(rm[1])) !== null) {
      cells.push(clean(cm[1]));
    }

    if (!cells.length) continue;

    const obj = {};
    headers.forEach((h, i) => {
      obj[h] = nullIfBlank(cells[i]);
    });

    rows.push(obj);
  }

  return rows;
}

function parseKeyValueTable(tableHtml) {
  if (!tableHtml) return {};

  const tbodyM = tableHtml.match(/<tbody[^>]*>([\s\S]*?)<\/tbody>/);
  const scope = tbodyM ? tbodyM[1] : tableHtml;

  const out = {};
  const rowRe = /<tr[^>]*>([\s\S]*?)<\/tr>/g;

  let rm;
  while ((rm = rowRe.exec(scope)) !== null) {
    const row = rm[1];
    const keyM = row.match(/<th[^>]*class="[^"]*desc[^"]*"[^>]*>([\s\S]*?)<\/th>/);
    const valM = row.match(/<td[^>]*>([\s\S]*?)<\/td>/);

    if (!keyM) continue;

    const key = clean(keyM[1]);
    if (!key) continue;

    out[key] = nullIfBlank(valM ? clean(valM[1]) : null);
  }

  return out;
}

function parseIndividualDetails(html) {
  const SKIP_IDS = new Set(['detail-box-features']);

  const leftM = html.match(
    /<div[^>]*class="[^"]*detail-channel[^"]*channel-left[^"]*"[^>]*>([\s\S]*?)<\/div><!-- detail-channel -->/
  );

  const scope = leftM ? leftM[1] : html;
  const boxes = [];

  const boxRe = /<div[^>]*id="(detail-box-[^"]+)"[^>]*>([\s\S]*?)<\/div>\s*(?=<div[^>]*id="detail-box-|<\/div><!-- untabbed-boxes)/g;

  let bm;
  while ((bm = boxRe.exec(scope)) !== null) {
    const id = bm[1];
    if (SKIP_IDS.has(id)) continue;

    const inner = bm[2];
    const titleM = inner.match(/<h3[^>]*>([\s\S]*?)<\/h3>/);
    const tableM = inner.match(/<table[^>]*>([\s\S]*?)<\/table>/);

    if (!titleM || !tableM) continue;

    const title = clean(titleM[1]);
    const items = parseKeyValueTable(tableM[1]);

    if (Object.keys(items).length) {
      boxes.push({ title, items });
    }
  }

  return boxes;
}

const input = {
  ...$('Random Wait').item.json,
  ...$json,
};

const html = input.data;

if (!input.detail_url) {
  throw new Error('Missing detail_url in Parse Result input');
}

if (typeof html !== 'string' || !html) {
  return { json: input };
}

const individual_details = parseIndividualDetails(html);

const workout_summary = parseTable(
  extractFirstTable(extractById(html, 'detail-box-other'))
);

const race_replay = parseTable(
  extractFirstTable(extractById(html, 'detail-box-splits'))
);

const { data, ...rest } = input;

const idp =
  rest.idp ||
  getQueryParam(rest.detail_url, 'idp');

const event_id =
  rest.event_id ||
  $('Edit Fields').first().json.event_id;

return {
  json: {
    ...rest,
    event_id,
    idp,
    individual_details,
    workout_summary,
    race_replay,
  },
};

